    const [a, b] = p.frame.split(':').map(Number), target = a / b, ia = iw / ih;
    let w = 1, h = 1;
    if (target > ia) h = ia / target; else w = target / ia;
    p.crop = { x: (1 - w) * (p.cropX ?? 0.5), y: (1 - h) * (p.cropY ?? 0.5), w, h };
