    if (ui.shape.kind === 'star') bar.append(optRange('Points', 3, 16, 1, ui.shape.points, String, (v) => { ui.shape.points = v; }), optRange('Inner', 0.15, 0.9, 0.01, ui.shape.inner, (v) => Math.round(v * 100) + '%', (v) => { ui.shape.inner = v; }));
