  doc.text.layers = recipeLayers(r).concat(doc.text.source === 'both' ? lineLayers : []);
  if (doc.text.source === 'lines') doc.text.source = 'photo';
  doc.text.sel = Math.max(0, recipeLayers(r).length - 1);
